<?php
declare(strict_types=1);
namespace Owr\M1;
if (!defined('ABSPATH')) exit;

/** Static UI text only. User content, storage keys and JSON are never translated. */
final class AdminText
{
    public static function text(string $english): string {
        if (!function_exists('determine_locale') || !str_starts_with(determine_locale(), 'ja')) return $english;
        return self::JA[$english] ?? $english;
    }
    public static function message(string $message): string {
        $english=array_search($message,self::JA,true);
        return self::text($english===false?$message:$english);
    }
